def parse_range(header, size):
    """
    Parse an RFC 7233 Range header for bytes.

    Args:
        header (str): The value of the Range header (e.g., "bytes=0-499").
        size (int): The total size of the resource in bytes.

    Returns:
        list: A list of (start, end) tuples representing inclusive byte offsets,
              or None if the header is unsatisfiable (all ranges are invalid).
    """
    if not header.startswith("bytes="):
        return None

    ranges_str = header[6:]  # Remove "bytes="
    if not ranges_str:
        return None

    ranges = []
    parts = ranges_str.split(",")

    for part in parts:
        part = part.strip()
        if not part:
            continue

        if "-" not in part:
            continue

        left, right = part.split("-", 1)
        left = left.strip()
        right = right.strip()

        start = None
        end = None

        # Handle suffix range: "-500"
        if left == "":
            if right == "":
                # "bytes=-" is invalid
                continue
            try:
                suffix_length = int(right)
                if suffix_length <= 0:
                    continue
                start = size - suffix_length
                if start < 0:
                    start = 0
                end = size - 1
            except ValueError:
                continue
        # Handle normal range: "0-499"
        elif right == "":
            # "bytes=500-" means from 500 to end
            try:
                start = int(left)
            except ValueError:
                continue

            if start >= size:
                # Range is unsatisfiable
                continue

            end = size - 1
        else:
            # Normal range with both start and end
            try:
                start = int(left)
                end = int(right)
            except ValueError:
                continue

            # Clamp end if it's past the last byte
            if end >= size:
                end = size - 1

            # If start is at or past size, this range is unsatisfiable
            if start >= size:
                continue

            # Ensure start <= end after clamping
            if start > end:
                continue

            ranges.append((start, end))

    if not ranges:
        return None

    return ranges
