class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.size = 0
        self.key_to_node = {}  # key -> Node
        self.freq_to_keys = {} # frequency -> set of keys
        self.min_freq = 0

    def _get_or_create_freq(self, freq):
        if freq not in self.freq_to_keys:
            self.freq_to_keys[freq] = set()
        return self.freq_to_keys[freq]

    def _remove_key_from_freq(self, key, freq):
        freq_set = self.freq_to_keys[freq]
        freq_set.remove(key)
        if not freq_set:
            del self.freq_to_keys[freq]
            if freq == self.min_freq:
                self.min_freq += 1

    def _add_key_to_freq(self, key, freq):
        self._get_or_create_freq(freq).add(key)

    def _update_node_freq(self, node):
        key = node.key
        old_freq = node.freq
        new_freq = old_freq + 1

        self._remove_key_from_freq(key, old_freq)
        node.freq = new_freq
        self._add_key_to_freq(key, new_freq)

    def get(self, key: int) -> int:
        if key not in self.key_to_node:
            return -1

        node = self.key_to_node[key]
        self._update_node_freq(node)
        return node.value

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return

        if key in self.key_to_node:
            node = self.key_to_node[key]
            node.value = value
            self._update_node_freq(node)
        else:
            if self.size >= self.capacity:
                # Evict the least frequently used (and least recently used within that freq)
                min_freq_set = self.freq_to_keys[self.min_freq]
                evict_key = min_freq_set.pop()
                del self.key_to_node[evict_key]
                self.size -= 1

            new_node = Node(key, value)
            self.key_to_node[key] = new_node
            self._add_key_to_freq(key, 1)
            self.size += 1
            if self.min_freq == 0:
                self.min_freq = 1

