    # Start searching from the next minute
    current = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    # Safety limit to prevent infinite loops (e.g., invalid expressions)
    max_iterations = 100000
    iterations = 0

    while iterations < max_iterations:
        iterations += 1

        # Check month
        if current.month not in month:
            # Move to next month
            if current.month == 12:
                current = current.replace(year=current.year + 1, month=1, day=1, hour=0, minute=0)
            else:
                current = current.replace(month=current.month + 1, day=1, hour=0, minute=0)
            continue

        # Check day-of-month and day-of-week rules
        dom_restricted = day_of_month != [i for i in range(1, 32)]
        dow_restricted = day_of_week != [i for i in range(7)]

        day = current.day
        dow = current.weekday()  # Monday=0, Sunday=6 in Python

        # Convert Python weekday to cron weekday (Sunday=0)
        cron_dow = (dow + 1) % 7

        if dom_restricted and dow_restricted:
            # Both restricted: match EITHER day-of-month OR day-of-week
            if day not in day_of_month and cron_dow not in day_of_week:
                # Move to next day
                current = current + timedelta(days=1)
                continue
        elif dom_restricted:
            # Only day-of-month restricted
            if day not in day_of_month:
                current = current + timedelta(days=1)
                continue
        elif dow_restricted:
            # Only day-of-week restricted
            if cron_dow not in day_of_week:
                current = current + timedelta(days=1)
                continue
        else:
