            # Move to next hour
            current = current.replace(minute=0) + timedelta(hours=1)
            continue

        # Check minute
        if current.minute not in minute:
            # Move to next minute
            current = current + timedelta(minutes=1)
            continue

        # If we reach here, we found a valid time
        return current

    raise ValueError("Could not find next fire time within reasonable limits")
