def deep_copy(obj):
    # Identity map to handle sharing and cycles: maps original object -> its copy
    memo = {}

    def _copy(o):
        # Base cases: immutable scalars are returned as-is
        if isinstance(o, (str, int, float, bool, type(None))):
            return o

        # Check if we have already copied this object (handles sharing and cycles)
        if o in memo:
            return memo[o]

        # Handle container types
        if isinstance(o, dict):
            new_dict = {}
            memo[o] = new_dict
            for k, v in o.items():
                new_dict[_copy(k)] = _copy(v)
            return new_dict

        if isinstance(o, list):
            new_list = []
            memo[o] = new_list
            for item in o:
                new_list.append(_copy(item))
            return new_list

        if isinstance(o, set):
            new_set = set()
            memo[o] = new_set
            for item in o:
                new_set.add(_copy(item))
            return new_set

        if isinstance(o, tuple):
            # Tuples are immutable, but we must copy their contents to preserve sharing/cycles
            new_tuple = tuple(_copy(item) for item in o)
            memo[o] = new_tuple
            return new_tuple

        # Fallback for other types (should not happen based on problem statement)
        return o

    return _copy(obj)
