        self._values = {}  # cell -> computed value (number)
        self._formulas = {}  # cell -> formula string
        self._deps = {}  # cell -> set of cells it depends on
        self._rev_deps = {}  # cell -> set of cells that depend on it

    def _parse_formula(self, formula_str):
        # Remove leading '='
        expr = formula_str[1:]
        tokens = []
        i = 0
        while i < len(expr):
            if expr[i].isspace():
                i += 1
                continue
            if expr[i] in '+-*/':
                tokens.append(expr[i])
                i += 1
            elif expr[i].isdigit():
                j = i
                while j < len(expr) and expr[j].isdigit():
                    j += 1
                tokens.append(int(expr[i:j]))
                i = j
            elif expr[i].isalpha():
                j = i
                while j < len(expr) and (expr[j].isalpha() or expr[j].isdigit()):
                    j += 1
                tokens.append(('REF', expr[i:j]))
                i = j
            else:
                raise ValueError(f"Invalid character in formula: {expr[i]}")
        return tokens

    def _evaluate(self, cell, visited=None):
        if visited is None:
            visited = set()
        if cell in visited:
            raise ValueError("Reference cycle detected")
        if cell not in self._formulas:
            return self._values.get(cell, 0)

        visited.add(cell)
        tokens = self._parse_formula(self._formulas[cell])
        result = self._eval_tokens(tokens, visited)
        return result

    def _eval_tokens(self, tokens, visited):
        if not tokens:
            return 0

        # Simple recursive descent for +, -, *, with proper precedence
        # We'll implement a two-pass approach: first handle *, then + and -

        # Pass 1: Handle multiplication
        i = 0
        while i < len(tokens):
            if isinstance(tokens[i], tuple) and tokens[i][0] == 'REF':
                # Check if next token is *
                if i + 1 < len(tokens) and tokens[i+1] == '*':
