                            right_val = self._eval_tokens([right], visited.copy())
                            left_val = self._eval_tokens([tokens[i]], visited.copy())
                            tokens[i] = left_val * right_val
                            tokens[i+1] = None  # Mark as consumed
                            tokens[i+2] = None  # Mark * as consumed
                            i += 3
                            continue
                    else:
