module.exports = function debounce(fn, wait, options) {
  if (typeof fn !== 'function') {
    throw new TypeError('Expected a function');
  }

  const leading = options && options.leading !== false;
  const trailing = options && options.trailing !== false;
  const maxWait = options && options.maxWait;

  let timeoutId;
  let lastCallTime;
  let lastArgs;
  let lastThis;
  let lastResult;

  function debounced() {
    const args = arguments;
    const thisArg = this;
    const currentTime = Date.now();

    if (maxWait && lastCallTime && currentTime - lastCallTime >= maxWait) {
      clearTimeout(timeoutId);
      lastCallTime = null;
    }

    if (!timeoutId) {
      lastCallTime = currentTime;
      lastArgs = args;
      lastThis = thisArg;
    }

    if (leading && !timeoutId) {
      lastResult = fn.apply(thisArg, args);
      if (!trailing) {
        return lastResult;
      }
    }

    if (trailing) {
      clearTimeout(timeoutId);
      timeoutId = setTimeout(function() {
        lastResult = fn.apply(lastThis, lastArgs);
        timeoutId = null;
        lastCallTime = null;
      }, wait);
    }

    return lastResult;
  }

  debounced.cancel = function() {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
  };

  debounced.flush = function() {
    if (timeoutId) {
      const result = fn.apply(lastThis, lastArgs);
      clearTimeout(timeoutId);
      timeoutId = null;
      lastCallTime = null;
      return result;
    }
    return lastResult;
  };

  return debounced;
};

