module.exports = function chunkAsync(source, size) {
  if (typeof size !== 'number' || size <= 0) {
    throw new Error('size must be a positive integer');
  }

  return async function* () {
    const buffer = [];
    let hasMore = true;

    while (hasMore) {
      // Pull up to `size` items, but stop if we already have enough
      // or if the source is exhausted.
      while (buffer.length < size && hasMore) {
        const item = source.next();
        if (item.done) {
          hasMore = false;
          break;
        }
        buffer.push(item.value);
      }

      if (buffer.length === 0) {
        // No items left and we couldn't pull any more
        break;
      }

      // Yield the current chunk
      yield buffer;

      // Clear buffer for next iteration
      buffer.length = 0;
    }

    // Ensure cleanup if the consumer stops early
    if (source.return) {
      await source.return();
    }
  };
};

