module.exports = function memoize(fn, keyFn) {
  const calls = { count: 0 };
  let cache = null;
  let keyGenerator = null;

  function generateKey(arg) {
    if (keyFn) {
      return keyFn(arg);
    }
    if (typeof arg === 'object' && arg !== null) {
      return arg; // WeakMap key
    }
    return arg; // Primitive key
  }

  function getCache() {
    if (cache === null) {
      if (keyFn) {
        cache = new Map();
      } else {
        cache = new WeakMap();
      }
    }
    return cache;
