  if (typeof obj !== 'object') return encodeURIComponent(String(obj));

  const parts = [];
  const keys = Object.keys(obj).sort();

  for (const key of keys) {
    const val = obj[key];
    if (val === null || val === undefined) continue;

    if (Array.isArray(val)) {
      if (val.length === 0) {
        parts.push(encodeURIComponent(key) + '[]');
      } else {
        for (const item of val) {
          parts.push(encodeURIComponent(key) + '[]=' + encodeURIComponent(String(item)));
        }
      }
    } else if (typeof val === 'object') {
      // Check if it's an array-like object (has numeric keys) or plain object
      const isObj = !Array.isArray(val);
      const subParts = [];
      const subKeys = Object.keys(val).sort();

      for (const subKey of subKeys) {
        const subVal = val[subKey];
        if (subVal === null || subVal === undefined) continue;

        let subKeyStr = subKey;
        if (Array.isArray(subVal)) {
          subKeyStr = subKey + '[]';
          for (const item of subVal) {
            subParts.push(subKeyStr + '=' + encodeURIComponent(String(item)));
          }
        } else if (typeof subVal === 'object') {
          subKeyStr = subKey + '[';
          const subSubParts = [];
          const subSubKeys = Object.keys(subVal).sort();
          for (const subSubKey of subSubKeys) {
            const subSubVal = subVal[subSubKey];
            if (subSubVal === null || subSubVal === undefined) continue;
            let subSubKeyStr = subSubKey;
            if (Array.isArray(subSubVal)) {
              subSubKeyStr = subSubKey + '[]';
              for (const item of subSubVal) {
                subSubParts.push(subSubKeyStr + '=' + encodeURIComponent(String(item)));
              }
            } else {
              subSubKeyStr = subSubKey + '=';
              subSubParts.push(subSubKeyStr + encodeURIComponent(String(subSubVal)));
            }
          }
          subParts.push(subKeyStr + subSubParts.join('&') + ']');
        } else {
          subParts.push(subKeyStr + '=' + encodeURIComponent(String(subVal)));
        }
      }
      parts.push(encodeURIComponent(key) + '[' + subParts.join('&') + ']');
    } else {
      parts.push(encodeURIComponent(key) + '=' + encodeURIComponent(String(val)));
    }
  }

