module.exports = function toposortTasks(tasks) {
  const taskMap = new Map(Object.entries(tasks));
  const result = new Map();
  const pending = new Set();
  const errors = new Map(); // name -> Error
  const completed = new Set();

  // Build dependency graph and detect cycles
  const visited = new Set();
  const recursionStack = new Set();
  const cycleError = new Error('Dependency cycle detected');

  function detectCycle(name) {
    if (recursionStack.has(name)) {
      return true;
    }
    if (visited.has(name)) {
      return false;
    }

    visited.add(name);
    recursionStack.add(name);

    const task = taskMap.get(name);
    if (task) {
      for (const dep of task.deps) {
        if (detectCycle(dep)) {
          return true;
        }
      }
    }

    recursionStack.delete(name);
    return false;
  }

  // Validate all tasks and detect cycles first
  for (const [name] of taskMap) {
    if (detectCycle(name)) {
      throw cycleError;
    }
  }

  // Check for unknown dependencies
  for (const [name, task] of taskMap) {
    for (const dep of task.deps) {
      if (!taskMap.has(dep)) {
        const err = new Error(`Unknown dependency: ${dep}`);
        errors.set(name, err);
      }
    }
  }

