  function getResolvedValue(depName) {
    if (completed.has(depName)) {
      return result.get(depName);
    }
    if (errors.has(depName)) {
      throw errors.get(depName);
    }
    if (pending.has(depName)) {
      throw new Error(`Circular dependency or missing result for: ${depName}`);
    }
    return undefined;
  }

