  async function runTask(name) {
    pending.add(name);

    const task = taskMap.get(name);
    if (!task) {
      throw new Error(`Task not found: ${name}`);
    }

    // Gather dependencies
    const depsValues = {};
    for (const dep of task.deps) {
      depsValues[dep] = getResolvedValue(dep);
    }

    try {
      const value = await task.run(depsValues);
      result.set(name, value);
      completed.add(name);
    } catch (err) {
      errors.set(name, err);
      completed.add(name);
    } finally {
      pending.delete(name);
    }
