export class Bus<E extends Record<string, unknown>> {
  private listeners = new Map<keyof E, Map<keyof E, ((payload: E[keyof E]) => void)[]>>();

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    if (!this.listeners.has(k)) {
      this.listeners.set(k, new Map());
    }
    const eventListeners = this.listeners.get(k)!;
    eventListeners.set(k, [...(eventListeners.get(k) || []), fn]);
    return () => {
      const eventListeners = this.listeners.get(k);
      if (eventListeners) {
        const listeners = eventListeners.get(k);
        if (listeners) {
          const index = listeners.indexOf(fn);
          if (index > -1) {
            listeners.splice(index, 1);
            if (listeners.length === 0) {
              eventListeners.delete(k);
              if (eventListeners.size === 0) {
                this.listeners.delete(k);
              }
            }
          }
        }
      }
    };
  }

  emit<K extends keyof E>(k: K, payload?: E[K]): void {
    const eventListeners = this.listeners.get(k);
    if (!eventListeners) return;

    const listeners = eventListeners.get(k);
    if (!listeners) return;

    // Check if the event type is void
    if (E[K] extends void) {
      listeners.forEach(fn => fn(payload as any));
    } else {
      if (payload === undefined) {
        throw new Error(`Event "${String(k)}" requires a payload.`);
      }
      listeners.forEach(fn => fn(payload));
    }
  }
}

