export type MatchResult<T, H> = H extends { [K in keyof H]: (...args: any[]) => infer R }
  ? { [K in keyof H]: R } extends { [K in keyof H]: any }
    ? { [K in keyof H]: R }
    : never
  : never;

export type Narrowed<T, K extends keyof T> = T extends { kind: infer U }
  ? U extends K
    ? T
    : never
  : never;

export function match<T extends { kind: string }, K extends keyof T['kind']>(
  value: T,
  handlers: {
    [P in K]: (variant: Narrowed<T, P>) => any;
  }
): MatchResult<T, { [P in K]: ReturnType<NonNullable<Extract<T['kind'], P>>> }> {
  const kind = value.kind;
  const handlerKeys = Object.keys(handlers) as K[];
  const variantKeys = Object.keys(value) as (keyof T)[];
  const kindKey = variantKeys.find(k => k === 'kind');

  if (!kindKey) {
    throw new Error('Value must have a "kind" property');
  }

  const kindValue = value[kindKey];
  const matchedKey = kindValue as K;

  if (!handlerKeys.includes(matchedKey)) {
    throw new Error(`No handler for kind "${matchedKey}"`);
  }

  return handlers[matchedKey](value as Narrowed<T, matchedKey>) as any;
}

// Type-level enforcement helpers
type HasAllVariants<T, K extends string> = K extends string
  ? T extends { kind: K }
    ? true
    : false
  : never;

type HasNoExtraVariants<T, K extends string> = K extends string
  ? string extends K
    ? false
    : K extends keyof T['kind']
      ? true
      : false
  : never;

// This module exports the match function with strict type checking
// The type system ensures:
// 1. All variants present in the union must have a handler
// 2. No handler can be provided for a variant not in the union
// 3. The return type is the union of all handler return types

export { match };

