export type Config = {
  name: string;
  age?: number;
  active: boolean;
};

export type RequiredKeys<T> = {
  [K in keyof T]: T[K] extends undefined ? never : K;
}[keyof T];

export type OptionalKeys<T> = {
  [K in keyof T]: T[K] extends undefined ? K : never;
}[keyof T];

export type BuilderState<T> = {
  data: Partial<T>;
  requiredKeys: Set<keyof T>;
  optionalKeys: Set<keyof T>;
};

export function builder<T extends Record<string, unknown>>() {
  const state: BuilderState<T> = {
    data: {} as Partial<T>,
    requiredKeys: new Set<keyof T>(),
    optionalKeys: new Set<keyof T>(),
  };

  // Infer required and optional keys based on whether the value is undefined
  for (const key of Object.keys(state.data) as Array<keyof T>) {
    if (state.data[key] === undefined) {
      state.requiredKeys.add(key);
    } else {
      state.optionalKeys.add(key);
    }
